Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — check without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
}

// Now demonstrate "not available": use a source-gen context that only knows about Person
var restricted = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (restricted.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person> on restricted: found");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> on restricted: NOT found (no exception!)");
}

if (restricted.TryGetTypeInfo<Order>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Order> on restricted: found");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Order> on restricted: NOT found (no exception!)");
